"Anyone remember why the sky is a portal?":"有人記得天空為什麼是傳送門嗎?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"聽說跳進礦井會從敵人那邊冒出來。我才不試。",
"The Swarm painted their visors red again. Show-offs.":"蜂群又把面罩塗成紅色了。愛現鬼。",
"Ore, ore… when do we get some oil?":"礦石、礦石……潤滑油什麼時候才有?",
"I dreamt I was a toaster. It was peaceful.":"我夢到自己是烤麵包機。很平靜。",
"Quiet. Too quiet.":"好安靜。太安靜了。",
"See that? Our base is above the Swarm base again. Portals, man.":"看到沒?蜂群基地上方又出現我們的基地了。傳送門啊,老兄。",
"Diman, if you're reading this — we need a vacation.":"Diman,如果你看到這個——我們需要放假。",
