"Select the HQ and train a builder (50 ore) — click to open the HQ panel":"選擇總部並訓練工程兵（50 礦石）——點擊即可開啟總部面板",
"Builders are trained only at the HQ: select the HQ (click it or F2) — its production panel opens on the right. Same for the mech factory, drone hub, airdock and outpost":"工程兵只能在總部訓練：選擇總部（點擊它或按 F2）——右側會開啟其生產面板。機甲工廠、無人機基地、空港和前哨也是一樣",
"The Build tab opens when a builder is selected; a \"Select nearest builder\" button; Z X C V B N K pick a builder automatically":"選取工程兵時會開啟「建造」分頁；另有「選擇最近的工程兵」按鈕；Z X C V B N K 會自動選擇工程兵",
"The Curator replaces the strategy tutorial: it suggests what to do as you play, points at the button and marks the map; turn it off on the panel or in Settings":"嚮導取代了戰略教學：遊戲中會提示該做什麼，以箭頭指出按鈕並在地圖上標記；可在面板或設定中關閉",
"Developer mode (main menu): unlimited ore, everything unlocked, instant build, the Arsenal — any weapon, class, vehicle, target dummies; your career is untouched":"開發者模式（主選單）：無限礦石、全部解鎖、瞬間建造、「軍械庫」——任意武器、兵種、載具、標靶假人；不會更動你的生涯",
"Phone: shooter buttons no longer cover the crosshair or weapon, strategy panels collapse, bigger buttons, a clear \"Strategy ⇄ Battle\" switch":"手機：射手按鈕不再遮擋準星和武器，戰略面板可收合，按鈕更大，「戰略 ⇄ 戰鬥」切換更清楚",
