"Select a builder: the \"⚒ Select nearest builder\" or \"⚒ Builder\" button.":"選擇工程兵：點「⚒ 選擇最近的工程兵」或「⚒ 工程兵」按鈕。",
"Select a builder: \"⚒ Select nearest builder\" on the right or click one.":"選擇工程兵：點右側的「⚒ 選擇最近的工程兵」，或直接點選工程兵。",
"Tap the marked vein ⛏ (glowing crystals), then \"✔ Build\". Mark off-screen — tap it to fly the camera there.":"點按標記的礦脈 ⛏（發光水晶），然後按「✔ 建造」。標記在畫面外時——點按它，鏡頭會飛過去。",
"Click the marked vein ⛏ — the glowing crystals (RMB/Esc — cancel). Mark off-screen — click it to fly the camera there.":"點選標記的礦脈 ⛏——發光的水晶（右鍵/Esc — 取消）。標記在畫面外時——點選它，鏡頭會飛過去。",
"Tap a spot for the {0}, then \"✔ Build\".":"點按「{0}」的建造位置，然後按「✔ 建造」。",
"Click a spot for the {0} (RMB/Esc — cancel).":"點選「{0}」的建造位置（右鍵/Esc — 取消）。",
"I am the Curator: I highlight the button and the spot on the map. \"✕\" turns me off.":"我是嚮導：我會標出該按的按鈕和地圖上的位置。「✕」可關閉我。",
"I am the Curator. I will suggest what to do as you play, highlighting the button and the spot on the map. Turn me off with \"✕\" here or the \"Curator\" button at the bottom right.":"我是嚮導。遊戲中我會提示該做什麼，標出按鈕和地圖上的位置。要關閉我，請按這裡的「✕」或右下角的「嚮導」按鈕。",
"The Swarm is at the base! \"All army\", then long-tap the enemies. A turret at the base helps too.":"蜂群逼近總部！按「全軍」，然後長按敵人。總部旁的砲塔也能幫忙。",
"The Swarm is at the base! Select troops (box or Ctrl+A) and RMB the enemies. A turret (Z) helps too.":"蜂群逼近總部！框選部隊（或按 Ctrl+A）並右鍵點敵人。總部旁的砲塔（Z）也能幫忙。",
"Camera: drag the map with a finger, two fingers — zoom and rotate. Move the camera.":"鏡頭：用手指拖曳地圖，雙指縮放並旋轉。移動一下鏡頭。",
"Camera: WASD or screen edges, wheel — height, Q/E — rotate. Move the camera.":"鏡頭：WASD 或螢幕邊緣，滾輪調整高度，Q/E 旋轉。移動一下鏡頭。",
"No builders — and nothing gets built without them. Select the HQ — click it or the \"⌂ HQ\" button.":"沒有工程兵——沒有他們就蓋不了任何建築。選擇總部——點它或按「⌂ 總部」按鈕。",
"Order a builder — the \"⚒ Builder\" button in the HQ panel (50 ore).":"訓練一名工程兵——總部面板中的「⚒ 工程兵」按鈕（50 礦石）。",
"We need ore — let us put an extractor on an ore vein.":"需要礦石——我們在礦脈上放一台採礦機。",
"Press \"Extractor\" (C) and place it on the glowing crystals of the vein — I marked it ⛏.":"按「採礦機」（C），把它放在礦脈發光的水晶上——我已標記為 ⛏。",
"Few troops. Select the HQ — squads are ordered there.":"兵力不足。選擇總部——小隊要在那裡訓練。",
"Order an \"Assault squad\" in the HQ panel.":"在總部面板中訓練一支「突擊小隊」。",
"Points give ore. Select a squad — tap it or the \"◈ Squad\" button on the right.":"佔領點能提供礦石。選擇一支小隊——點按它，或按右側的「◈ 小隊」按鈕。",
"Points give ore. Select a squad — tap it or the \"◆ Army\" card at the top.":"佔領點能提供礦石。選擇一支小隊——點按它，或點上方的「◆ 軍隊」卡片。",
"Points give ore. Select a squad — click it or its card in the \"◆ Army\" panel on the left.":"佔領點能提供礦石。選擇一支小隊——點選它，或點左側「◆ 軍隊」面板中的卡片。",
"Long-tap point {0} — the squad goes to capture it.":"長按佔領點 {0}——小隊會前往佔領。",
"RMB on point {0} — the squad goes to capture it.":"右鍵點佔領點 {0}——小隊會前往佔領。",
"POINT ":"佔領點 ",
"The base is under attack — let us build a turret.":"總部遭到攻擊——蓋一座砲塔吧。",
"Press \"Turret\" (Z) and place it at the base, facing the enemy.":"按「砲塔」（Z），把它放在總部旁、靠近敵人的位置。",
"Enough ore for a mech factory — it makes tanks and vehicles.":"礦石足夠蓋機甲工廠了——它能生產坦克和載具。",
"Press \"Mech factory\" (B) and place it at the base (a flat spot inside the dashed ring).":"按「機甲工廠」（B），把它放在總部（虛線圈內的平地上）。",
"{0} is idle — select it and give an order: {1} a point or an enemy.":"{0} 閒置中——選擇它並下令：{1}目標點或敵人。",
"The mech factory is ready. Select it to order a tank.":"機甲工廠已完工。選擇它來訂製坦克。",
"Order a \"Tank\" in the factory panel.":"在工廠面板中訂製一輛「坦克」。",
"More extractors — more ore. There is a free vein nearby.":"採礦機越多，礦石越多。附近還有一條空的礦脈。",
"\"Extractor\" (C) on the marked vein ⛏.":"把「採礦機」（C）放在標記的礦脈 ⛏ 上。",
"Pick a power and click an enemy cluster.":"選擇一種技能，然後點選敵人聚集處。",
"Command points are piling up — the \"✺ Powers\" tab: artillery, recon, drop pod.":"指揮點越積越多——到「✺ 技能」分頁：砲擊、偵察、空降艙。",
"Low on ore? Tap \"ORE\" at the top — see where income comes from and how to boost it.":"礦石不夠？點按上方的「礦石」——查看收入來源以及如何提升。",
"Want to fight yourself? Select a squad and press \"▶ Possess\".":"想親自上陣？選擇一支小隊並按「▶ 附身」。",
