"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"財團重裝槍手現在是真正帶骨架的 3D 模型：會待機、行走、持槍衝鋒、邊移動邊開火，被摧毀時會倒下",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"模型會貼合隕石表面的法線，轉動上身瞄準並雙手持機槍；遠處的動畫更新頻率較低，以維持 FPS",
"New in v6.5":"v6.5 新內容",
"Barracks":"兵營",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"步兵：突擊小隊、重裝槍手、狙擊手、偵察兵、空降艙；護甲與武器升級。",
"Ore depot":"礦石倉庫",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"工程兵會把水晶送到這裡。蓋在水晶田旁邊——路程更短,礦石更多。",
"Tanks and vehicles. Requires Barracks.":"坦克與載具。需要兵營。",
