"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"噴射背包 II 與空降兵(噴射背包菁英)。需要機甲工廠,於 6:00 解鎖。",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"在己方據點建立的前進基地:工程兵、水晶交付點、增援。",
