"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"噴射背包與飛行器稍後才會解鎖——趁現在趕快蓋好防空與砲塔。同時先蓋兵營和機甲工廠。",
"Lone heavy gunner":"孤狼重裝槍手",
"Crystals nearby are depleted — builder is idle":"附近的水晶已採完——工程兵閒置中",
