"carrying ore (+{0})":"搬運礦石中(+{0})",
"mining crystals":"採集水晶中",
"No crystal field near a drop-off":"資源交付點附近沒有可用的水晶田",
"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"採集水晶:工程兵在綠色水晶田裝滿貨物,再運到總部/倉庫。也可以右鍵點水晶。",
