"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"小隊會跟著你。開啟 ☰ → 「暫停」→ 「小隊跟隨」方塊——會變成「單獨行動」。",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"已選取工程兵——點按下方其卡片上的「◆ 採集水晶」（或點按綠色水晶）。",
