"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"你已學會建造基地、下令部隊、指揮並投入戰鬥。接下來是真正的對戰：導覽員會在遊戲過程中提供提示。",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"你已學會移動、飛行、射擊、掩護並指揮小隊。接下來是真正的對戰。",
