"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"安全的沙盒：敵人仍是假人，沒有人會對你開火。只有你真正做出動作，步驟才會算數。",
"Show others (training for the other device)":"顯示其他(給其他裝置的訓練)",
"Old training (v7.1)":"舊版訓練 (v7.1)",
"Back to the normal device mode":"恢復一般裝置模式",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"切換到其他裝置的訓練會以該模式重新載入頁面(電腦 — 滑鼠與鍵盤,手機 — 觸控;在電腦上可用 Chrome 測試觸控:F12 → 手機圖示)。",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"訓練 ×4：電腦版與手機版各有獨立的「戰略」與「射手」逐步課程。安全的沙盒搭配標靶人偶，會醒目標示該按的按鈕，並有箭頭、動態按鍵、滑鼠與手勢示範；只有完成真正的操作才算過關，可「重做此步驟」，頂部顯示進度，結束時有獎勵",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"訓練選單會自動顯示適合你裝置的課程;「顯示其他」可在任何裝置上看到全部四種;「舊版訓練 (v7.1)」仍然保留",
"New in v7.2":"v7.2 新內容",
"NEW IN v7.2":"v7.2 新內容",
"No grenades left":"手榴彈用完了",
"Rocket and grenade recharging · {0} s":"火箭彈與手榴彈充能中 · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"左側 — 移動,右側 — 視角 · 點按敵人 — 火箭彈 / 手榴彈 · 點按 2 次 — 反射 · 點按 3 次 — 砲擊",
"Less":"更少",
"More":"更多",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"附近有敵方載具或建築 — 點按它:發射火箭彈。",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"敵人很多 — 在右側空白處快速點按 2 次:反射會減慢時間。",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"瞄準敵人密集處並點按 3 次 — 砲擊。",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"左手指 — 移動,右手指 — 視角。準星對準敵人時會自動開火。",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"左側邊緣的 ⇑ — 噴氣背包:點按跳躍,按住飛行。",
"Old v7.2 layout":"舊版 v7.2 配置",
"Drag a finger on the right half of the screen — a look stick appears under it.":"在螢幕右半邊拖動手指 — 手指下方會出現視角搖桿。",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"觸碰左側並滑動 — 手指下方會出現搖桿。走到綠色標記處。",
"Hold the \"Jet\" button at the left edge.":"按住左側邊緣的「噴氣背包」按鈕。",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"用右搖桿將準星對準標靶人偶 — 準星對準目標時,你的士兵會自動開火。",
"Tap the dummy on the screen — a rocket flies.":"點按螢幕上的標靶人偶 — 發射火箭彈。",
"Tap the dummy — a grenade flies in an arc, right at it.":"點按標靶人偶 — 手榴彈會以拋物線直接飛向它。",
"Double tap an empty spot on the right quickly.":"在右側空白處快速點按 2 次。",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"弱機專用的輕量模式:降低解析度,無陰影與扭曲效果,機器人與粒子減半,上限 30 FPS;FPS < 25 時會自動降低解析度。手機上預設開啟(設定 → 畫面 →「輕量模式」;或在連結中加 ?lite=1 / ?lite=0)。",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"手機:全新操作配置。左側 — 移動,右側 — 視角(兩支搖桿都會出現在手指下方)。只用左手指 —「自動」;右手指也操作時,只有準星對準敵人,士兵才會自動開火。點按敵人 — 火箭彈或手榴彈,點按 2 次 — 反射,點按 3 次 — 砲擊。自動換彈。噴氣背包 — 左側邊緣的按鈕。底部兩角留空,小地圖在角落,提示可用叉叉關閉,任務目標可收合。舊版配置:設定 → 手機。",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"提示(彈出視窗與向導)— 設定中只有一個開關。你操控的是誰(士兵或載具類型)— HUD 中的「你:…」標籤。步槍與機槍的瞄準鏡改為透明。「軍械庫」面板固定在右側,可收合也可關閉。「無小隊單人」模式 (J) 已移除。AI 戰略官的語音不再連續重複同一句話。坦克新增砲塔與車體方向指示器。戰略教學開始時游標不再消失。",
