"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"手機:三種搖桿模式。只用左搖桿 —「自動」(磁吸強,子彈較弱)。只用右搖桿 — 自動開啟瞄準,磁吸更強,射擊更準。同時使用兩支 — 無瞄準,磁吸與精準度較低。右側的 👁 按鈕可隱藏/恢復介面。",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"手機:戰略已簡化 — 僅有工程兵與建築。左側為卡片(工程兵、總部、兵營…):點按 — 鏡頭飛過去,底部列直接顯示可建造/可生產的項目。「投入戰鬥」在左上角。軍隊會自行作戰。完整戰略 — 設定 → 手機。",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"附身 — 兩個選項:「小隊」與「載具」(手機上載具預設關閉 — 由 AI 駕駛)。載具關閉時,在友軍載具旁按 E(手機:右側按鈕)— 操作它的砲:載具自行行駛,你負責射擊。舊的自訂兵種順序在「進階」中。附身時,單位會透過無線電回應。",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"智慧提示:基礎提示在第 2 次啟動後自動關閉,但遊戲仍會提醒你一直沒用過的功能。選項:基礎 / 進階 / 稀有,另有提示與向導語音的獨立開關。",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"反射會因擊殺而充能(連殺充能更多)。隊友落後或陣亡時,AI 戰略官會空降新隊友到你身邊(比一般增援更貴)。已併入 v7.2gfx 的畫面與音效:翻騰的爆炸、煙霧、碎片、礦井與坑洞音效。建置日期現在是真實的。",
