"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"生涯與存檔不受影響。對戰中,同一個選單就是右上角的「🛠 選單」按鈕{0}。",
"New developer match":"新的開發者對戰",
"all unlocked, endless ore, instant build, arsenal":"全部解鎖,礦石無限,即時建造,軍械庫",
"Trainings — all 4":"訓練 — 全部 4 種",
"PC and phone (strategy and shooter)":"電腦與手機(戰略與射手)",
"Cinema: split screen":"電影:分割畫面",
"strategist bot left, shooter bot right":"左為機器人 AI 戰略官,右為機器人射手",
"Cinema: everything built":"電影:全部建造完畢",
"both bases built and upgraded — for footage":"雙方基地皆已建造並升級 — 供拍攝使用",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"電影模式 — 分割畫面:左側為機器人 AI 戰略官(俯視基地與軍隊),右側為第一人稱機器人射手。底部按鈕(以及按鍵 S、P):「分割畫面」與「★ 全部建造完畢」— 雙方基地皆已建造並升級,供拍攝使用。",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"核心和貫穿隕石的隧道都不見了——隕石是實心的，戰鬥只在地表進行。",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"手機:👁 會隱藏 HUD,但保留噴氣背包、⇆、搖桿和任務標記。「◎ 瞄準」(僅限右手指)——吸附力明顯更強、範圍更廣;三種模式的吸附力在 設定 → 操作 →「進階」。在載具砲座上,按鈕會顯示「下車」。",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"訓練：手機只顯示手機版訓練，PC 只顯示 PC 版。4 個全在「🛠 開發者」選單裡。開發者模式和軍械庫合併成同一個選單了（戰鬥中——右上角「🛠 選單」，PC 上按 F8）。",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"畫面風格「Dendy（8 位元）」和「16 位元」：設定 → 畫面 →「畫面風格」（詳情——⚙ 按鈕）。如果對戰開始後約 10 秒內 FPS 低於 24，Dendy 會自動開啟（低於 20 就繼續放大像素，120 行）；點「恢復正常」提示會永久恢復一般畫面。你在選單裡的選擇永遠優先。",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D 環境模型（廢墟、殘骸、防禦工事）——只收錄評價良好的，依需求串流載入。關閉方式：設定 → 畫面 →「新 3D 環境模型」。",
