"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"士兵建造：在己方工地按 E（手機：「進入」）——你的士兵親自建造，附近隊友會幫忙。如果工程兵都在忙，戰略家會請你幫忙——出現「工地」標記。",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"戰略家標記：戰略家會在你附近的敵軍密集處標上 ⌖——8 s 後砲擊落下，附近的己方多管火箭「冰雹」也會齊射。你從戰略模式發動的砲擊同樣有「冰雹」支援。",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"貨櫃和墜毀衛星裡有武器補給箱（70 m 內可見 📦）：按 E——重機槍 90 s、燃燒彈或火箭彈，外加補滿手榴彈。匍匐：Ctrl——趴下 / 站起（更低、更穩、更準，但移動慢）。",
