"Anonymous statistics (no names or emails)":"匿名統計（不含姓名或電子郵件）",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"電影式分割畫面、無核心和隧道、士兵建造、戰略家標記、補給箱、匍匐、開發者選單",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"手機三種搖桿模式、簡易戰略、載具砲座、峽谷地形、小隊兵種、炸藥",
