"Link copied":"連結已複製",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"「▶ 立即開玩」——選單的第一個按鈕：在傳送門天空下短暫飛越，然後直接投入戰鬥（按任意鍵或點按可跳過）。",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"命中有手感：金屬聲和火花、準星處的擊殺標記（爆頭——黃色）、×N 連殺、爆炸帶來的平滑晃動、關鍵擊殺時的慢動作。晃動、慢動作和提示都可以在設定中關閉。",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"對戰結果：時間、擊殺數、最佳連殺、★ MVP 和最佳小隊、對戰卡片——「⇪ 分享」，PNG 或遊戲連結。",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"左側資源下方有「現在該做什麼」提示：戰略家的命令、待佔領的點、蜂群的進攻。✕ 或 F7——收合。",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"關閉或最小化分頁時，戰鬥會自動存檔——選單中的「⟲ 繼續」。",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 仍保留在「🕘 遊戲版本」選單中——萬一你不喜歡新版。現在會傳送匿名統計（不含姓名和電子郵件）；可在設定中關閉。",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"「立即開玩」、命中回饋、附分享卡片的對戰結果、「該做什麼」提示、自動存檔",
"and older: v7.5, v7.4, milestones v1–v7.0":"以及更早：v7.5、v7.4、里程碑 v1–v7.0",
"New in v7.6":"v7.6 新內容",
"NEW IN v7.6":"v7.6 新內容",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"對戰前選擇陣營：「財團」（穿著動力裝甲的重型步兵，裝甲和砲兵）或「蜂群」（速度、無人機群、帶扭曲效果的重型射擊）。AI 操控另一方。你的選擇會被記住。",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"每個陣營都有自己的載具和獨有內容：財團——坦克「犀牛」和「陶瓷裝甲板」，蜂群——「無人機群」和「相位噴射背包」。平衡已透過機器人對戰驗證。",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"爆炸彈坑:砲擊、火箭彈和戰車砲會在隕石上炸出坑洞——你可以在坑裡走動、行駛,也能躲進去掩蔽。",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"士兵第三人稱視角(V,會記住設定;手機上在「操控」裡)以及平滑的載具鏡頭,並附有砲彈落點標記。",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 仍保留在「🕘 遊戲版本」選單中,新版不合口味的話可以切換回去。",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"財團/蜂群陣營對戰前可選擇、爆炸彈坑、第三人稱視角",
"and older: v7.6, v7.5, milestones v1–v7.0":"以及舊版:v7.6、v7.5、里程碑 v1–v7.0",
