"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"在你的部隊附近空投一個箱子:彈藥、手榴彈、火箭彈、武器零件、維修包。",
"\"Grad\" rocket strike":"「冰雹」火箭打擊",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"3 秒後向大範圍發射 16 枚火箭彈——比砲擊更快、範圍更廣。",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"支援:補給箱、偵察、「冰雹」、砲擊(然後按 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"警告:蜂群「冰雹」正瞄準你的區域!",
"Warning! Rocket salvo on our position!":"警告!我方陣地遭到火箭齊射!",
"take the supply crate":"拿取補給箱",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"隕石上的異常(第 1 波):「歌唱礦脈」——發光的綠色水晶,會嗡鳴並以節奏脈衝打擊附近所有人;「漩渦」會拉扯並摔人,「爆裂者」在鐵樁間放電弧,「火盆」會在腳下燃起火焰,「酸霧」和「透鏡」(會折彎子彈和你的視野)四處漂移。",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"異常可以提前察覺(嗡鳴、發光、熱浪扭曲)。可用手榴彈、火箭彈或螺栓(在異常旁按 E)讓它放電:它會進入休眠,有時留下一件有利有弊的遺物。小隊會用無線電預警,敵人(和友軍)有時會誤闖進去——把他們引過去!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"用指揮點呼叫支援:戰鬥中有 4 種(手機上是 📡)——補給箱、偵察掃描、「冰雹」火箭打擊、瞄準處砲擊。戰略家只有在偵察掃描後才能在地圖上看到異常。",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"補給箱出現在舊遠征隊的廢墟、總部附近以及已建成的建築旁:彈藥、手榴彈、火箭彈、武器零件(可解鎖配件)。",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 仍保留在「🕘 遊戲版本」選單中。異常可以在設定中關閉。",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"異常(「歌唱礦脈」及另外 5 種)、用螺栓和手榴彈放電、遺物、用指揮點呼叫支援、補給箱",
