"Close":"關閉",
"Anomalies on the meteor":"隕石上的異常",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"角落的 ☰ 可開啟暫停選單:繼續、重新開始、訓練、畫面、設定、主選單(需確認)。手機:右上角 ☰(戰鬥操作在「⚡ 動作」磁貼);PC:右上角的「☰ 選單」按鈕或 Esc。",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"畫面預設一律為一般模式——只有你自己選擇時才會用 Dendy:「畫面:一般 / Dendy(8 位元)/ 16 位元」切換開關就在主選單和暫停選單中。如果遊戲嚴重卡頓,會跳出附有「開啟 Dendy」按鈕的提示。",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"手機和平板:右側的「✋」動作按鈕只在附近有事可做時才會出現——「拿取」(藏匿處、箱子)、「上車」(載具、砲塔、火砲)、「建造」、「下車」、在異常旁「丟螺栓」。你也可以直接點按高亮的物件。",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"手機,戰略模式:手指按住約 0.3 秒(手機震動,出現黃色圓環)再拖曳——框選;一般滑動是移動鏡頭。右側也有「框選」按鈕;訓練中的「框選」步驟,點按小隊選取也算完成。",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"手機:小按鈕更容易點到,📡 支援清單更大,戰略面板不再遮住暫停和結算畫面。v7.8 仍保留在「🕘 遊戲版本」選單中。",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"手機和 PC 的 ☰ 選單、不再自動切換 Dendy、觸控「✋」按鈕、手機框選",
"16-bit":"16 位元",
"Lagging? Try the Dendy graphics — they are lighter.":"卡頓嗎?試試 Dendy 畫面——比較省效能。",
