"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"手指按住地面約 0.3 秒——手機震動並出現黃色圓環——然後不放開直接拖曳:就會拉出框選。也可以用右側的「框選」按鈕。直接點按小隊也行。",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"iPhone 要全螢幕:「分享」⬆ →「加入主畫面」——遊戲開啟時就不會有 Safari 的工具列。",
"Open portal-meteor.pages.dev for that.":"請為此開啟 portal-meteor.pages.dev。",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"點按 — 選取 · 點地面 — 移動 · 長按 — 命令選單 · 長按並拖曳 — 框選 · 雙指 — 縮放",
"Robo-ninja":"機器忍者",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"刺客英雄:瞬閃衝刺、武士刀、手裏劍。會自行穿梭敵方區域,將機器人砍成碎片。每方 1 名。",
"Shadow protocol":"「暗影」協議",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"研究:在兵營解鎖機器忍者。需要已建成的機甲工廠。",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"英雄(每方 1 名):會自行穿梭敵方區域,將機器人砍成碎片;你也可以附身並手動操作。",
