"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ 自動:她會自行跳躍穿梭敵方區域並砍殺。搖桿 / WASD 可暫停 1.5 秒",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ 手動:點按敵人 — 衝刺並斬擊,滑動 — 揮砍,🛡 — 格擋",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ 手動操作:左鍵 — 武士刀,右鍵 — 格擋,Shift — 瞬閃,Q — 手裏劍,G — 傳送",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ 忍者：點按敵人——衝刺並斬擊，右側滑動——揮砍，● ——攻擊，🛡 ——格擋（抓準時機＝招架），⇑ ——閃現，✦ ——手裡劍，◎ ——傳送，AUTO ——由她自行行動",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ 忍者：左鍵——武士刀（按住——重斬），右鍵——格擋（抓準時機＝招架），Shift/Z——閃現，Q——手裡劍，G——傳送至準星處，空中跳躍——二段跳／蹬牆跑，{0}——AUTO",
