"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor 電台：遊戲內直接收聽 EDMITRY 的 100 多首曲目——點按 📻 按鈕（電腦：按 5 鍵，[ ] 切換曲目）。音樂隨選串流，不會讓遊戲變肥大；音量與自動播放可在設定中調整，另有「在 Spotify 收聽」連結。",
