"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"右側的 📻 是 Portal Meteor 電台：戰鬥時收聽 EDMITRY 的音樂。",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0}——Portal Meteor 電台：戰鬥時收聽 EDMITRY 的音樂。[ ] 切換曲目。",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor 電台（EDMITRY）：音量",
"Radio: start by itself in battle":"電台：戰鬥中自動開啟",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"機器忍者：手持武士刀的改造人。在兵營完成「暗影協議」研究後解鎖（需要機甲工廠）。她會自行傳送到敵方區域，將敵人斬成碎片（沒有血——只有火花），能衝刺、投擲手裡劍，並與敵方忍者決鬥。附身於她——可選 AUTO 模式或手動操控（手機上有專屬按鈕）。",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor 電台：遊戲內直接收聽 EDMITRY 的 103 首曲目。按 5 鍵（可重新綁定），手機上——☰ → 設定 → 音效。音量與「戰鬥中自動開啟」在設定中調整；遇到爆炸與無線電語音時，音樂會自動降低音量。",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"新語言：烏茲別克語與塔吉克語——完整支援；中文、西班牙語、葡萄牙語——部分支援。選單中「新對戰」旁新增語言選擇。",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"手機：「隱藏圖示」👁 會把剩餘按鈕整理成靠右緣的整齊一列；直向模式不再重疊；iPhone——遊戲不再與 Safari 手勢衝突，且「分享 → 加入主畫面」可全螢幕啟動。",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"承襲 v7.8.1：角落的 ☰ 選單（暫停、重新開始、訓練、畫面）、不再自動切換 Dendy、手機上的 ✋ 動作按鈕。v7.8.1 與 v7.8 仍保留在「🕘 遊戲版本」選單中。",
