"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"友軍偶爾會請求支援：無線電呼叫、「請求」卡片和 ✋ 標記。小隊被壓制 — 消滅附近的敵人。獎勵：士兵乘空降艙從基地出發、越野車車廂的槍、砲手座位或軌道掩護。不想接 — 按 ✕ 或直接無視。",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"老兵偵察兵「夜梟」提供一個任務。Y — 接受（N — 拒絕）。前往 ★ 標記，清除守衛，並在飛行員旁停留 3 s — 他會加入你的小隊。",
