"You run and shoot yourself. That is how you have played so far.":"你親自奔跑射擊。到目前為止你都是這樣玩的。",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"從上方俯瞰並指揮整支軍隊:建造基地、派出小隊。軍隊沒有你也會自行作戰。",
