"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"提示已收起 — 點「?」可再次開啟。離開課程:☰ → 「離開課程」",
"◎ precise":"◎ 精準",
"○ running":"○ 跑動",
"◉ run + aim":"◉ 跑動 + 瞄準",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"「指揮官」模式、陣營頭目、活的隕石(地形、生態區、天氣、異常、動物群)、活的世界;更快、手把支援、平板、百科、回饋模式、手機簡易介面",
"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"一個按鈕切換三種模式:射手(你親自作戰)、全新的指揮官(帶領一支小隊,每種單位有 4 個技能)和戰略家。手機上採用簡易介面:按鈕更少,模式會在戰鬥過程中逐步解鎖。",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"活的隕石:岩石、山脊、平頂山中的機庫、熔岩/冰/甲烷湖、三種生態區、局部天氣、全新異常與本地動物群。",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"陣營玩法各不相同:蜂群挖掘隧道並自我再生,財團設置路障並維修載具。從第 12 分鐘起——「Bastion」「堡壘」與「Reaper」「收割者」頭目登場;你可以附身己方的頭目。",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"活的世界:你的士兵會透過無線電請求支援(附帶獎勵),英雄會發布任務,戰線僵持時會觸發「戰局逆轉」行動。膠囊艙、補給箱和打擊從總部經由天空傳送門發射。",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"更快(單幀耗時最多減半)、所有模式支援手把、平板版面、涵蓋遊戲內所有內容的百科、回饋模式 — 一鍵即可儲存附截圖的筆記。",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"所有新文字已翻譯成烏茲別克語、塔吉克語、中文、西班牙語、葡萄牙語和希伯來語。v7.9 的機器忍者和無線電保持不變;v7.9 位於「🕘 遊戲版本」選單中。",
"New in v8.15":"v8.15 新內容",
"NEW IN v8.15":"v8.15 新內容",
"Fixes: the camera card hides under pause and menus, building labels are smaller and fainter, clean screen (F9/👁) also hides world markers.":"修正:鏡頭卡片會在暫停和選單開啟時隱藏,建築上方的標籤更小更淡,簡潔畫面 (F9/👁) 也會隱藏世界標記。",
